			                    app.lookup("dsCaseTrprList").setValue(cnt, "PIC_INST_NM"               , voReturnVal[i]["PIC_INST_NM"]);           //담당자기관명
			                    app.lookup("dsCaseTrprList").setValue(cnt, "ACBG_SE_CD"                , voReturnVal[i]["ACBG_SE_CD"]);            //학력구분
			                    app.lookup("dsCaseTrprList").setValue(cnt, "GRDTN_STTS_SE_CD"          , voReturnVal[i]["GRDTN_STTS_SE_CD"]);      //졸업상태구분
			                    app.lookup("dsCaseTrprList").setValue(cnt, "DDLN_CRTR_YMD"             , voReturnVal[i]["DDLN_CRTR_YMD"]);         //마감기준년월
			                    app.lookup("dsCaseTrprList").setValue(cnt, "INST_NO"                   , voReturnVal[i]["INST_NO"]);               //기관번호
			                    app.lookup("dsCaseTrprList").setValue(cnt, "UNT_TASKWK_SE_CD"          , voReturnVal[i]["UNT_TASKWK_SE_CD"]);      //단위업무구분코드
			                    app.lookup("dsCaseTrprList").setValue(cnt, "DDLN_YM"                   , voReturnVal[i]["DDLN_YM"]);               //마감년월
			                    app.lookup("dsCaseTrprList").setValue(cnt, "DDLN_YN"                   , voReturnVal[i]["DDLN_YN"]);               //마감여부
			                    app.lookup("dsCaseTrprList").setValue(cnt, "DDLN_APLCN_CRTR_SE_CD"     , voReturnVal[i]["DDLN_APLCN_CRTR_SE_CD"]); //마감적용기준구분코드
