			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			 // 미지원/삭제 코드 선택 확인
			     var bFlag = true;
			     var sMsg  = "";
			 
			     var comList = AppUtil.getComponentList(app, "grpData", "combobox");
			     for(var i=0; i<comList.length; i++) {
			         var comObj = comList[i];
			 
			         var sText       = comObj.text;
			         var sFiledLabel = comObj.fieldLabel;
			 
			         if(comObj.enabled && !comObj.readonly) {
			             if(sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			                 bFlag = false;
			 
			                 if(ValueUtil.isNull(sMsg)) {
			                     sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                 } else {
			                     sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                 }
			             }
			         }
			     }
			     
			     comList = AppUtil.getComponentList(app, "grpData", "radiobutton");
			     for(var i=0; i<comList.length; i++) {
			         var comObj = comList[i];
			 
			         var sText       = comObj.text;
			         var sFiledLabel = comObj.fieldLabel;
			 
			         if(comObj.enabled && !comObj.readonly) {
			             if(sText.indexOf('삭제') > -1 || sText.indexOf('미지원') > -1) {
			                 bFlag = false;
			 
			                 if(ValueUtil.isNull(sMsg)) {
			                     sMsg = sFiledLabel + "을(를) 확인해 주세요.";
			                 } else {
			                     sMsg = sMsg + "\n" + sFiledLabel + "을(를) 확인해 주세요.";
			                 }
			             }
			         }
			     }
			 
			     if(!bFlag) {
			         util.Msg.alert(app, sMsg);
			         return false;
			     } 
			     
			    // 프리폼 필수값 유효성 체크 (저장 confirm 전에 체크)
			    if (!util.validate(app, "grpCaseMtgInfoSub")) return false; // 사례회의 정
			    
			    var dsCaseTrprList = app.lookup("dsCaseTrprList");
			    if(dsCaseTrprList.getRowCount() == 0) {
			        util.Msg.alert(app, "대상자를 등록해주시기 바랍니다.");
			        return false;
			    } else {
			        if(dsCaseTrprList.getRowCount() == dsCaseTrprList.getRowStatedCount(cpr.data.tabledata.RowState.DELETED)) {
			            util.Msg.alert(app, "대상자를 등록해주시기 바랍니다..");
			            return false;
			        }            
			    }
			    
			    var dsCaseMtgPic = app.lookup("dsCaseMtgPic");
			    if(dsCaseMtgPic.getRowCount() == 0) {
			        util.Msg.alert(app, "회의 담당자를 등록해주시기 바랍니다.");
			        return false;
			    } else {
			        if(dsCaseMtgPic.getRowCount() == dsCaseMtgPic.getRowStatedCount(cpr.data.tabledata.RowState.DELETED)) {
			            util.Msg.alert(app, "회의 담당자를 등록해주시기 바랍니다.");
			            return false;
			        }            
			    }    

			    if (!util.validate(app, "grpCaseTrprList")) return false;   // 대상자 목록    
			    if (!util.validate(app, "grdCaseMtgAtdrn2")) return false;  // 참석자 목록    
			    if (!util.validate(app, "grdCaseMtgPic2")) return false;    // 담당자 목록    
			    
			    
			    var psTitle = "집단사례회의 저장";
			    var psMsgId = "집단사례회의를 저장 하시겠습니까?";
			    
			    util.Msg.confirm(app, psMsgId, null, function(){
			        
			//        doSave();
			        var vcFileUpload = app.lookup("cmnsinglefileupload1");
			        vcFileUpload.send(doSave);                
			        
			    }, function(){
			        /*pfCancleCallbackFn*/
			        
			    }, psTitle);
			    
			}

